#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <vector>
struct Node { int value; Node* next; };
Node* StableThreeGroups(Node* p, int pivot) {
    std::array<Node*, 3> heads = {{nullptr, nullptr, nullptr}};
    std::array<Node*, 3> tails = {{nullptr, nullptr, nullptr}};
    while (p != nullptr) {
        Node* saved = p->next;
        p->next = nullptr; // 원래 다음 연결을 끊고 각 그룹의 끝을 항상 명확히 합니다.
        const std::size_t group = p->value < pivot ? 0 : (p->value == pivot ? 1 : 2);
        if (tails[group] != nullptr) tails[group]->next = p;
        else heads[group] = p;
        tails[group] = p;
        p = saved;
    }
    Node* result = nullptr;
    Node* tail = nullptr;
    for (std::size_t g = 0; g < 3; ++g) {
        if (heads[g] == nullptr) continue;
        if (tail != nullptr) tail->next = heads[g];
        else result = heads[g];
        tail = tails[g];
    }
    return result;
}
int main() {
    std::size_t cases = 0, combinations = 1;
    const std::array<int, 5> pivots = {{std::numeric_limits<int>::min(), -1, 0, 1,
                                      std::numeric_limits<int>::max()}};
    for (std::size_t n = 0; n <= 7; ++n) {
        if (n != 0) combinations *= 3;
        for (std::size_t pattern = 0; pattern < combinations; ++pattern)
            for (int pivot : pivots) {
                std::vector<Node> nodes(n);
                std::size_t code = pattern;
                for (std::size_t i = 0; i < n; ++i) {
                    nodes[i].value = static_cast<int>(code % 3) - 1; code /= 3;
                    nodes[i].next = (i + 1 < n) ? &nodes[i + 1] : nullptr;
                }
                std::vector<Node*> expected;
                for (int g = 0; g < 3; ++g)
                    for (std::size_t i = 0; i < n; ++i)
                        if ((g == 0 && nodes[i].value < pivot) ||
                            (g == 1 && nodes[i].value == pivot) ||
                            (g == 2 && nodes[i].value > pivot)) expected.push_back(&nodes[i]);
                Node* p = StableThreeGroups(n ? &nodes[0] : nullptr, pivot);
                for (Node* wanted : expected) { assert(p == wanted); p = p->next; }
                assert(p == nullptr); ++cases;
            }
    }
    std::cout << "partition cases: " << cases << ", pointer stability: passed\n";
}
